Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Ltac zto pc := repeat (lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).

Section CANSEC1. Context {rc : runConstT}.
Section X4S33.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX1) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis TOK : x1_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (2 * 2^tl)) (x1_bytes' cells).
  Hypothesis LCB : zlen cbs = 2 * 2^tl.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl + 1.
  Hypothesis D0 : 0 <= DST.
  Hypothesis DP : 0 < dcap -> 8 <= DST.
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 2 * 2^tl <= lo.
  Hypothesis DJ1 : DT + 4 + 2 * 2^tl <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation XB l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).
  Notation X4F' mm spl bd4 := (X4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm spl bd4).

  (* [comment removed for export] *)
  Variables (O3 L3 Q3 v24 v32 v48 v80 v96 v120 v128 v136 v152 c4 bc4 ptr4 st4 : Z) (j0 j72 j88 j104 jp : list byte).
  Variables (y8 y9 y10 y12 y16 y19 y24 y25 y26 y27 : word).
  Hypothesis HL3 : 6 <= O3 /\ 1 <= L3 /\ O3 + L3 <= n.
  Hypothesis HQ3 : 0 < Q3 <= dcap.
  Notation SPL := (SPL3 v24 v32 (tl + 256 * mtl) v48 (DST + Q3) (SS + O3) v80 v96 v120 v128 v136 (SS + O3 + 8) v152 j0 j72 j88 j104).
  Notation BD := (BD4 c4 bc4 ptr4 st4 jp).

  Notation ST pc mm xra t0 t1 t2 a1 a3 a4 a5 a7 x22 x23 t3 t4 t5 t6 :=
    (MS (mkR xra (Z_to_bv 64 (SP + -416)) gp tp t0 t1 t2 y8 y9 y10 a1 y12 a3 a4 a5 y16 a7
             (Z_to_bv 64 (DT + 4)) y19 (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + Q3)) x22 x23 y24 y25 y26 y27 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Hypothesis CONT : forall mm (xra t1 a1 a3 a4 a5 a7 x22 x23 t3 t4 t5 t6 : word),
    X4F' mm SPL BD ->
    evt psegs POST (ST 0x1a59c mm xra (Z_to_bv 64 v24) t1 (Z_to_bv 64 (SS + O3)) a1 a3 a4 a5 a7 x22 x23 t3 t4 t5 t6).

  Notation A3 l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47
                      O3 L3 Q3 v24 v32 v48 v80 v96 v120 v128 v136 v152 c4 bc4 ptr4 st4 j0 j72 j88 j104 jp
                      y8 y9 y10 y12 y16 y19 y24 y25 y26 y27 HL3 HQ3 CONT) (only parsing).
  Notation HD pc mm q pt bits xc t2 a1 a3 t3 t4 t5 t6 :=
    (ST pc mm xc (Z_to_bv 64 (DST + Q3 - 3)) (Z_to_bv 64 (64 - tl)) t2 a1 a3 (Z_to_bv 64 67064) (Z_to_bv 64 (DST + q))
        (Z_to_bv 64 64) (Z_to_bv 64 bits) (Z_to_bv 64 (SS + O3 + pt)) t3 t4 t5 t6).

  (* [comment removed for export] *)
  Lemma x33_x47c : forall q mm (xc t0 t1 a1 a3 a4 a7 x22 x23 t3 t4 t5 t6 : word),
    X4F' mm SPL BD -> 0 <= q <= Q3 ->
